        ("South Korea", "Seoul", "Busan"), ("Norway", "Oslo", "Bergen"), ("Poland", "Warsaw", "Kraków"),
        ("Switzerland", "Bern", "Zurich"), ("Nigeria", "Abuja", "Lagos"), ("Vietnam", "Hanoi", "Ho Chi Minh City"),
